            : null,
      }),
    );
  }
  const champion = tournament?.matches.at(-1)?.winner;
  return (
    <section className="tournament">
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && <TournamentSetup names={names} change={setNames} start={start} />}
      {tournament && (
        <>
          {complete ? (
            <p className="champion">
              Champion:{' '}
              {champion === null || champion === undefined ? '' : tournament.players[champion]}
            </p>
          ) : (
            <>
              <TournamentPlay
                key={`${revision}:${tournament.matchIndex}:${turnIndex(tournament)}`}
                ref={turn}
                tournament={tournament}
                snapshot={snapshot}
                publish={publish}
                finish={finish}
                started={() => {
                  setTournament(startTurn(tournament));
                  heading.current?.focus();
                }}
              />
              <div className="tournament-actions">
                {tournament.phase === TournamentPhase.turnDone && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setSnapshot(null);
                      setTournament(nextTurn(tournament));
                    }}
                  >
                    Next turn
                  </button>
                )}
                {tournament.phase === TournamentPhase.matchDone && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setSnapshot(null);
                      setTournament(nextMatch(tournament));
                    }}
                  >
                    Next match
                  </button>
                )}
                <button className="control" type="button" onClick={() => confirm(back)}>
                  Leave tournament
                </button>
              </div>
            </>
          )}
          <Bracket tournament={tournament} />
        </>
      )}
      {(!tournament || complete) && (
        <button
          className="control"
          type="button"
          onClick={() => {
            if (!tournament && names.some((name) => name.trim())) confirm(back);
            else back();
          }}
        >
          Back to game
        </button>
      )}
      <section className="tournament-exchange" aria-label="Tournament exchange">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          className="control"
          id="tournament-json"
          value={json}
          maxLength={TOURNAMENT_MAX_BYTES}
