        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportCurrent}>
            Export tournament
          </button>
          <button
            className="control"
            type="button"
            onClick={load}
            aria-describedby="tournament-notice"
          >
            Load tournament
