                    className="control"
                    type="button"
                    onClick={() => {
                      setNames(item.players);
                      setTournament(item);
                      setSnapshot(null);
                    }}
                  >
                    Champion: {winner === undefined || winner === null ? '' : item.players[winner]}{' '}
                    · {item.players.length} players
                  </button>
                </li>
              );
            })}
          </ol>
        </section>
      )}
      {tournament && history.blocked && <p>Progress won't be saved on this device.</p>}
    </section>

